{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C55"],
      "claim": "Delmopinol, a lipophilic locally acting oral agent, has very low systemic bioavailability after oral administration, supporting low F for the similarly lipophilic, locally acting query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Testosterone undecanoate, a long-chain ester prodrug, has absolute oral bioavailability of 6.83 ± 3.32%, well below 20%, supporting low F for the long-chain ester-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C58"],
      "claim": "Dimethandrolone undecanoate, another long-chain undecanoate ester, shows poor and inconsistent oral bioavailability, supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Batimastat, a peptide-like hydroxamate, showed poor oral bioavailability, supporting low F for the peptide-ester-like query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "One nitrendipine record reported 40% oral bioavailability, above the 20% threshold, but this dihydropyridine is structurally unrelated to the query and is an outlier against the consistent low-F data.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is orlistat, a locally acting lipase inhibitor with negligible systemic absorption; transferable evidence from lipophilic, poorly absorbed oral drugs and long-chain ester prodrugs consistently indicates oral bioavailability far below 20%, so the prediction is low.",
  "evidence_gaps": [
    "No direct orlistat bioavailability record is present in the supplied evidence; the decision relies on recognized query pharmacology and transferable analogs.",
    "A few nitrendipine records report F above 20%, but their structural and mechanistic transferability to the query is very low."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

